1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// A scenario: the one customer the MHPCO deals with, and the steps they file.
15	pub struct Scenario {
16	    pub customer: Customer,
17	    pub steps: Vec<Step>,
18	}
19	
20	/// One operation the customer asks the MHPCO to perform.
21	pub enum Step {
22	    Quote {
23	        items: Vec<Item>,
24	    },
25	    Claim {
26	        /// Zero-based index of the quote step that created the policy.
27	        policy: usize,
28	        incident: Incident,
29	    },
30	}
31	
32	/// What the MHPCO reports for one step of a scenario.
33	#[derive(Debug)]
34	pub enum StepResult {
35	    Quote { premium: u64 },
36	    Claim { payout: u64, remaining_cap: u64 },
37	}
38	
39	/// Why the MHPCO refuses to process a scenario at all.
40	#[derive(Debug)]
41	pub enum ScenarioError {
42	    /// The step a claim named as its policy is no earlier quote step.
43	    NoPolicyAtStep { step: usize },
44	    Quote(QuoteError),
45	    Claim(ClaimError),
46	}
47	
48	impl std::fmt::Display for ScenarioError {
49	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
50	        match self {
51	            Self::NoPolicyAtStep { step } => {
52	                write!(formatter, "step {step} created no policy to claim against")
53	            }
54	            Self::Quote(error) => error.fmt(formatter),
55	            Self::Claim(error) => error.fmt(formatter),
56	        }
57	    }
58	}
59	
60	/// Why the MHPCO refuses to quote a premium at all.
61	#[derive(Debug)]
62	pub enum QuoteError {
63	    /// The catalogue lists no item of this type.
64	    UnknownItemType { item_type: String },
65	}
66	
67	impl std::fmt::Display for QuoteError {
68	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
69	        match self {
70	            Self::UnknownItemType { item_type } => {
71	                write!(formatter, "the MHPCO does not insure a {item_type}")
72	            }
73	        }
74	    }
75	}
76	
77	/// Why the MHPCO refuses to settle a claim at all.
78	#[derive(Debug)]
79	pub enum ClaimError {
80	    /// A damage was reported with a negative amount.
81	    NegativeDamageAmount { amount: i64 },
82	    /// The policy covers no item of this type at all.
83	    ItemNotInsured { item_type: String },
84	    /// More damages of this item type were reported than the policy covers.
85	    MoreDamagesThanInsuredItems { item_type: String },
86	}
87	
88	impl std::fmt::Display for ClaimError {
89	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
90	        match self {
91	            Self::NegativeDamageAmount { amount } => {
92	                write!(formatter, "a damage amount of {amount} is not a loss")
93	            }
94	            Self::ItemNotInsured { item_type } => {
95	                write!(formatter, "the damaged {item_type} is not insured by this policy")
96	            }
97	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
98	                formatter,
99	                "more {item_type} damages were reported than the policy insures"
100	            ),
101	        }
102	    }
103	}
104	
105	/// What the MHPCO settles on a claim: the payout and the cap left on the
106	/// policy afterwards.
107	#[derive(Debug)]
108	pub struct ClaimResult {
109	    pub payout: u64,
110	    pub remaining_cap: u64,
111	}
112	
113	/// The single customer a scenario is quoted for.
114	pub struct Customer {
115	    pub years_with_mhpco: u32,
116	}
117	
118	pub struct Item {
119	    pub item_type: String,
120	    pub material: String,
121	    pub enchantment: u32,
122	    pub cursed: bool,
123	}
124	
125	const PROCESSING_FEE: u64 = 5;
126	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
127	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
128	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
129	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
130	
131	const COMPONENT_INSURANCE_VALUE: u64 = 250;
132	const COMPONENT_BASE_PREMIUM: u64 = 25;
133	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
134	const COMPONENT_BLOCK_SIZE: usize = 3;
135	const CURSE_SURCHARGE_PERCENT: u64 = 50;
136	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
137	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
138	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
139	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
140	const LOYALTY_YEARS: u32 = 2;
141	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
142	
143	/// Components, such as runes and moonstones, are the parts the MHPCO insures
144	/// alongside main items and the only items the building-block offer covers.
145	fn is_component(item: &Item) -> bool {
146	    matches!(item.item_type.as_str(), "rune" | "moonstone")
147	}
148	
149	/// What the MHPCO price list says about one main item: the value it is insured
150	/// for and the base premium it costs to insure. The list states both figures on
151	/// one line per item, and the office never learns one without the other.
152	struct PriceListEntry {
153	    insurance_value: u64,
154	    base_premium: u64,
155	}
156	
157	/// The MHPCO price list for main items, or nothing at all when the catalogue
158	/// does not list that type. This is the one place the roster of insurable main
159	/// items is written down: being listed here is what it means for the office to
160	/// insure a type.
161	fn price_list_entry(item_type: &str) -> Option<PriceListEntry> {
162	    let (insurance_value, base_premium) = match item_type {
163	        "sword" => (1000, 100),
164	        "amulet" => (600, 60),
165	        "staff" => (800, 80),
166	        "potion" => (400, 40),
167	        _ => return None,
168	    };
169	    Some(PriceListEntry {
170	        insurance_value,
171	        base_premium,
172	    })
173	}
174	
175	/// The MHPCO insures the components it recognises and the main items its price
176	/// list names; it insures nothing else.
177	fn is_in_catalogue(item: &Item) -> bool {
178	    is_component(item) || price_list_entry(&item.item_type).is_some()
179	}
180	
181	/// A reported damage must be a loss, never a negative amount.
182	fn check_every_damage_amount_is_a_loss(incident: &Incident) -> Result<(), ClaimError> {
183	    match incident.damages.iter().find(|damage| damage.amount < 0) {
184	        Some(negative) => Err(ClaimError::NegativeDamageAmount {
185	            amount: negative.amount,
186	        }),
187	        None => Ok(()),
188	    }
189	}
190	
191	/// The MHPCO can only price the items its catalogue lists.
192	fn check_every_item_is_in_the_catalogue(items: &[Item]) -> Result<(), QuoteError> {
193	    match items.iter().find(|item| !is_in_catalogue(item)) {
194	        Some(unknown) => Err(QuoteError::UnknownItemType {
195	            item_type: unknown.item_type.clone(),
196	        }),
197	        None => Ok(()),
198	    }
199	}
200	
201	/// The price-list line a main item is priced and insured by. The catalogue
202	/// guard has already refused anything the list does not name, so a main item
203	/// the office has accepted is always listed.
204	fn listed(item: &Item) -> PriceListEntry {
205	    price_list_entry(&item.item_type).expect("the catalogue lists this item type")
206	}
207	
208	/// The base premium one insured item earns. Every component is priced alike;
209	/// a main item is priced by its price-list line.
210	fn base_premium(item: &Item) -> u64 {
211	    if is_component(item) {
212	        return COMPONENT_BASE_PREMIUM;
213	    }
214	    listed(item).base_premium
215	}
216	
217	/// The building-block offer is reserved for a group of exactly 3 alike
218	/// components; a larger group does not qualify, it is priced per component.
219	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
220	    alike_component_count == COMPONENT_BLOCK_SIZE
221	}
222	
223	/// The price the MHPCO charges for one group of alike components: the
224	/// building-block offer when the group qualifies, otherwise per component.
225	fn component_group_base_premium(count: usize) -> u64 {
226	    if qualifies_as_building_block(count) {
227	        COMPONENT_BLOCK_BASE_PREMIUM
228	    } else {
229	        count as u64 * COMPONENT_BASE_PREMIUM
230	    }
231	}
232	
233	/// How many entries fall under each key a list of items is grouped by. The
234	/// MHPCO tallies items this way wherever a rule counts like with like: the
235	/// claim side groups by catalogue type to match damages against cover, the
236	/// premium side by alike-group key to recognise a building block.
237	fn count_by_item_type<'a>(
238	    item_types: impl Iterator<Item = &'a str>,
239	) -> BTreeMap<&'a str, usize> {
240	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
241	    for item_type in item_types {
242	        *counts.entry(item_type).or_insert(0) += 1;
243	    }
244	    counts
245	}
246	
247	/// Two components are "alike" when they share this key. For the MHPCO,
248	/// alike means the very same catalogue type: a rune and a moonstone are
249	/// never alike, so mixed component types form no building block.
250	fn alike_group_key(item: &Item) -> &str {
251	    &item.item_type
252	}
253	
254	/// The policy base premium: the sum of all insured items' base premiums,
255	/// with alike components priced per group so a block can be recognised.
256	fn policy_base_premium(items: &[Item]) -> u64 {
257	    let main_items_total: u64 = items
258	        .iter()
259	        .filter(|item| !is_component(item))
260	        .map(base_premium)
261	        .sum();
262	
263	    let alike_component_groups = count_by_item_type(
264	        items
265	            .iter()
266	            .filter(|item| is_component(item))
267	            .map(alike_group_key),
268	    );
269	
270	    main_items_total
271	        + alike_component_groups
272	            .values()
273	            .map(|count| component_group_base_premium(*count))
274	            .sum::<u64>()
275	}
276	
277	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
278	#[derive(Clone, Copy)]
279	enum Debtor {
280	    Customer,
281	    Mhpco,
282	}
283	
284	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
285	/// settles the direction by itself once it is known who owes whom: an amount
286	/// the customer owes is rounded up, an amount the office owes is rounded down.
287	/// Intermediate amounts stay fractional; only the final amount is rounded.
288	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
289	    match owed_by {
290	        Debtor::Customer => amount.ceil() as u64,
291	        Debtor::Mhpco => amount.floor() as u64,
292	    }
293	}
294	
295	/// A policy-wide modifier is measured against the policy base premium, the
296	/// sum of all item base premiums, never against a single item.
297	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
298	    policy_base_premium * percent as f64 / 100.0
299	}
300	
301	/// Every item in a quote is treated as a first insurance, so the initial
302	/// assessment surcharge is charged on the whole policy base premium.
303	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
304	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
305	}
306	
307	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
308	/// highly enchanted. This is the premium-side threshold; the claim-side
309	/// reimbursement clause judges enchantment by its own, stricter threshold.
310	fn is_highly_enchanted(item: &Item) -> bool {
311	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
312	}
313	
314	/// An item-specific risk surcharge is charged on the base premium of the
315	/// affected item, never on the policy total.
316	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
317	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
318	}
319	
320	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
321	/// item that brings two of them is surcharged for each.
322	fn item_risk_surcharge(item: &Item) -> f64 {
323	    let mut surcharge = 0.0;
324	    if item.cursed {
325	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
326	    }
327	    if is_highly_enchanted(item) {
328	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
329	    }
330	    surcharge
331	}
332	
333	/// Item-specific modifiers apply to the base premium of the affected item,
334	/// never to the policy total, so the policy owes the sum of the items' own
335	/// risk surcharges.
336	fn item_risk_surcharges(items: &[Item]) -> f64 {
337	    items.iter().map(item_risk_surcharge).sum()
338	}
339	
340	/// A long-standing customer, with at least two years of business with the
341	/// MHPCO, has earned the loyalty discount.
342	fn is_long_standing(customer: &Customer) -> bool {
343	    customer.years_with_mhpco >= LOYALTY_YEARS
344	}
345	
346	/// The loyalty discount is a policy-wide modifier, so it is measured against
347	/// the policy base premium.
348	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
349	    if is_long_standing(customer) {
350	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
351	    } else {
352	        0.0
353	    }
354	}
355	
356	/// A contract is a follow-up when the customer already holds at least one
357	/// other contract with the MHPCO; the customer's very first is not.
358	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
359	    contracts_already_held > 0
360	}
361	
362	/// Every contract after the customer's first earns the follow-up discount. It
363	/// is a policy-wide modifier, so it is measured against the policy base premium.
364	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
365	    if is_follow_up_contract(contracts_already_held) {
366	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
367	    } else {
368	        0.0
369	    }
370	}
371	
372	/// What the customer's standing with the MHPCO adds to or takes off the policy
373	/// base premium: the net of every policy-wide surcharge and discount. Positive
374	/// amounts raise the premium, negative amounts lower it.
375	fn policy_wide_modifiers(
376	    customer: &Customer,
377	    contracts_already_held: u32,
378	    policy_base_premium: f64,
379	) -> f64 {
380	    first_insurance_surcharge(policy_base_premium)
381	        - loyalty_discount(customer, policy_base_premium)
382	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
383	}
384	
385	/// The premium the policy earns before the processing fee: the policy base
386	/// premium, plus what the items' own risks cost, plus what the customer's
387	/// standing adjusts.
388	fn modified_policy_premium(
389	    customer: &Customer,
390	    contracts_already_held: u32,
391	    items: &[Item],
392	) -> f64 {
393	    let policy_base_premium = policy_base_premium(items) as f64;
394	    policy_base_premium
395	        + item_risk_surcharges(items)
396	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
397	}
398	
399	/// The MHPCO adds its processing fee to every premium at the very end, after
400	/// every surcharge and discount has been settled.
401	pub fn quote_premium(
402	    customer: &Customer,
403	    contracts_already_held: u32,
404	    items: &[Item],
405	) -> Result<u64, QuoteError> {
406	    check_every_item_is_in_the_catalogue(items)?;
407	    Ok(rounded_in_mhpco_favor(
408	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
409	        Debtor::Customer,
410	    ))
411	}
412	
413	/// Damage to a very highly enchanted item is reimbursed at only half the
414	/// damage amount. This claim-side threshold is deliberately stricter than, and
415	/// separate from, the premium-side high-enchantment risk surcharge: an item can
416	/// be enchanted enough to cost more to insure yet not enough to be halved.
417	fn is_reimbursed_by_half(item: &Item) -> bool {
418	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
419	}
420	
421	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
422	/// before the deductible is taken off. Full reimbursement is the MHPCO's
423	/// standing position: it is both what an item with no clause receives and what
424	/// the dragon-material clause prescribes, so that clause asks for no share of
425	/// its own. Only the halving clause departs from full reimbursement, and it
426	/// wins wherever it applies.
427	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
428	    if is_reimbursed_by_half(damaged_item) {
429	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
430	    } else {
431	        damage.amount as f64
432	    }
433	}
434	
435	/// The deductible applies per damage event, after the reimbursement clauses.
436	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
437	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
438	}
439	
440	/// Which insured item a reported damage refers to. A damage names only a
441	/// catalogue type, so the policy is searched for an item of that type; the
442	/// reimbursement clauses are judged against the item found here, not the report.
443	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
444	    items
445	        .iter()
446	        .find(|item| item.item_type == damage.item_type)
447	        .expect("the damaged item is insured by this policy")
448	}
449	
450	/// What the MHPCO owes for an incident filed against a policy: the sum of the
451	/// reimbursements its damages earn, rounded in the office's favor at the end.
452	/// This is the tally inside a settlement, not an operation of its own: it knows
453	/// nothing of admissibility or of the cap, so only `claim` may speak for it.
454	fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
455	    let total: f64 = incident
456	        .damages
457	        .iter()
458	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
459	        .sum();
460	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
461	}
462	
463	/// What one insured item is insured for. Every component is insured alike; a
464	/// main item is insured for the value its price-list line names.
465	fn insurance_value(item: &Item) -> u64 {
466	    if is_component(item) {
467	        return COMPONENT_INSURANCE_VALUE;
468	    }
469	    listed(item).insurance_value
470	}
471	
472	/// The insurance sum of a policy is the sum of its items' insurance values.
473	fn insurance_sum(items: &[Item]) -> u64 {
474	    items.iter().map(insurance_value).sum()
475	}
476	
477	/// The total payout per policy is capped at twice the insurance sum.
478	fn policy_cap(items: &[Item]) -> u64 {
479	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
480	}
481	
482	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
483	/// but never more than the cap the policy has left, and reports the cap that
484	/// survives the payout.
485	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
486	    let payout = earned.min(available_cap);
487	    ClaimResult {
488	        payout,
489	        remaining_cap: available_cap - payout,
490	    }
491	}
492	
493	/// How much of its cap a policy still has to pay out with, once earlier claims
494	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
495	/// exhausted cap is simply nothing left, never a debt the policy owes back.
496	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
497	    policy_cap(items).saturating_sub(cap_already_consumed)
498	}
499	
500	/// How many items of a catalogue type a policy insures. A type the policy never
501	/// mentions is insured none of: the MHPCO holds no cover for what it did not
502	/// write down.
503	fn insured_count_of(insured_counts: &BTreeMap<&str, usize>, item_type: &str) -> usize {
504	    insured_counts.get(item_type).copied().unwrap_or(0)
505	}
506	
507	/// Every reported damage must be covered by an insured item of its own. The
508	/// office compares the damages it was sent against the policy type by type, so a
509	/// type damaged twice needs two insured items of that type to stand. One
510	/// comparison decides admissibility; how far it falls short decides which
511	/// refusal the claim earns -- a type the policy does not cover at all is refused
512	/// as uninsured, a type covered by too few items as an over-count.
513	fn check_policy_covers_every_damage(
514	    items: &[Item],
515	    incident: &Incident,
516	) -> Result<(), ClaimError> {
517	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
518	    for (item_type, reported) in
519	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
520	    {
521	        let insured_of_that_type = insured_count_of(&insured, item_type);
522	        if insured_of_that_type == 0 {
523	            return Err(ClaimError::ItemNotInsured {
524	                item_type: item_type.to_string(),
525	            });
526	        }
527	        if reported > insured_of_that_type {
528	            return Err(ClaimError::MoreDamagesThanInsuredItems {
529	                item_type: item_type.to_string(),
530	            });
531	        }
532	    }
533	    Ok(())
534	}
535	
536	/// What the MHPCO settles on an incident filed against a policy: what the
537	/// incident earns, limited by the cap the policy has left. The office first
538	/// satisfies itself that the claim is admissible at all; an inadmissible claim
539	/// is refused whole, and nothing is paid out on it.
540	pub fn claim(
541	    items: &[Item],
542	    incident: &Incident,
543	    cap_already_consumed: u64,
544	) -> Result<ClaimResult, ClaimError> {
545	    check_every_damage_amount_is_a_loss(incident)?;
546	    check_policy_covers_every_damage(items, incident)?;
547	    Ok(settled_within_cap(
548	        claim_payout(items, incident),
549	        cap_remaining_on(items, cap_already_consumed),
550	    ))
551	}
552	
553	/// What the MHPCO has on record about a customer's dealings so far as it works
554	/// through their scenario: how many contracts they already hold, and how much
555	/// of each policy's cap earlier claims have already drawn down. Both are
556	/// written up as the office goes, and both are read back by later steps.
557	#[derive(Default)]
558	struct ScenarioLedger {
559	    contracts_already_held: u32,
560	    cap_consumed_by_policy: BTreeMap<usize, u64>,
561	}
562	
563	impl ScenarioLedger {
564	    /// Every quote writes a new contract into the customer's record, so the
565	    /// next quote is one further along their history with the office.
566	    fn record_new_contract(&mut self) {
567	        self.contracts_already_held += 1;
568	    }
569	
570	    /// How much of its cap a policy has already paid out on, before this claim.
571	    fn cap_consumed_by(&self, policy: usize) -> u64 {
572	        self.cap_consumed_by_policy.get(&policy).copied().unwrap_or(0)
573	    }
574	
575	    /// A settled payout draws down the cap of the policy it was filed against,
576	    /// leaving that much less for the policy's later claims.
577	    fn record_payout_against(&mut self, policy: usize, payout: u64) {
578	        *self.cap_consumed_by_policy.entry(policy).or_insert(0) += payout;
579	    }
580	}
581	
582	/// Steps are processed in order: each quote writes a policy a later claim can
583	/// refer to by its step index, and each claim draws down that policy's cap.
584	pub fn process_scenario(scenario: &Scenario) -> Result<Vec<StepResult>, ScenarioError> {
585	    let mut ledger = ScenarioLedger::default();
586	    scenario
587	        .steps
588	        .iter()
589	        .map(|step| process_step(scenario, step, &mut ledger))
590	        .collect()
591	}
592	
593	/// What one step of a scenario earns, read against and written back into the
594	/// record the office keeps of the customer's dealings so far.
595	fn process_step(
596	    scenario: &Scenario,
597	    step: &Step,
598	    ledger: &mut ScenarioLedger,
599	) -> Result<StepResult, ScenarioError> {
600	    match step {
601	        Step::Quote { items } => {
602	            let premium =
603	                quote_premium(&scenario.customer, ledger.contracts_already_held, items)
604	                    .map_err(ScenarioError::Quote)?;
605	            ledger.record_new_contract();
606	            Ok(StepResult::Quote { premium })
607	        }
608	        Step::Claim { policy, incident } => {
609	            let settled = claim(
610	                insured_items_of(scenario, *policy)?,
611	                incident,
612	                ledger.cap_consumed_by(*policy),
613	            )
614	            .map_err(ScenarioError::Claim)?;
615	            ledger.record_payout_against(*policy, settled.payout);
616	            Ok(StepResult::Claim {
617	                payout: settled.payout,
618	                remaining_cap: settled.remaining_cap,
619	            })
620	        }
621	    }
622	}
623	
624	/// The items insured by the policy a quote step created. A claim names its
625	/// policy by the step index of the quote that wrote it.
626	///
627	/// What the office should do when that index names no quote at all -- a step
628	/// out of range, or a claim step rather than a quote -- is not something the
629	/// MHPCO has ruled on, so neither answer below is a decision the office has
630	/// made: an out-of-range index is left to panic, and an index naming a claim
631	/// step is read as a policy insuring nothing.
632	fn insured_items_of(scenario: &Scenario, policy: usize) -> Result<&[Item], ScenarioError> {
633	    match scenario.steps.get(policy) {
634	        Some(Step::Quote { items }) => Ok(items),
635	        _ => Err(ScenarioError::NoPolicyAtStep { step: policy }),
636	    }
637	}
