/// The items insured by the policy a quote step created. A claim names its
/// policy by the step index of the quote that wrote it.
///
/// What the office should do when that index names no quote at all -- a step
/// out of range, or a claim step rather than a quote -- is not something the
/// MHPCO has ruled on, so neither answer below is a decision the office has
/// made: an out-of-range index is left to panic, and an index naming a claim
/// step is read as a policy insuring nothing.
fn insured_items_of(scenario: &Scenario, policy: usize) -> Result<&[Item], ScenarioError> {
    match scenario.steps.get(policy) {
        Some(Step::Quote { items }) => Ok(items),
        _ => Err(ScenarioError::NoPolicyAtStep { step: policy }),
    }
}

